package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class TokenBuffer_writeNumber_TriageGen1Test {

    private ObjectCodec codec;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        codec = new ObjectMapper();
        tokenBuffer = new TokenBuffer(codec);
    }

    @Test
    public void testWriteNumber_PositiveDouble() throws IOException {
        double value = 123.45;
        tokenBuffer.writeNumber(value);

        // Verify the token type recorded is a NUMBER
        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        // To verify the actual content, we simulate serialization to a generator
        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);

        // Jackson's TokenBuffer.writeNumber(double) calls generator.writeNumber(double)
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NegativeDouble() throws IOException {
        double value = -0.001;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        double value = 0.0;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_Infinity() throws IOException {
        double value = Double.POSITIVE_INFINITY;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_NaN() throws IOException {
        double value = Double.NaN;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_LargeDouble() throws IOException {
        double value = Double.MAX_VALUE;
        tokenBuffer.writeNumber(value);

        assertEquals(JsonToken.VALUE_NUMBER_FLOAT, tokenBuffer.firstToken());

        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        tokenBuffer.serialize(mockGenerator);
        verify(mockGenerator).writeNumber(value);
    }

    @Test
    public void testWriteNumber_ThrowsIOException() throws IOException {
        // Create a generator that throws an exception when writeNumber is called
        JsonGenerator mockGenerator = mock(JsonGenerator.class);
        doThrow(new IOException("Simulated IO Error")).when(mockGenerator).writeNumber(any(double.class));

        tokenBuffer.writeNumber(1.0);

        try {
            tokenBuffer.serialize(mockGenerator);
            org.junit.Assert.fail("Expected IOException to be thrown");
        } catch (IOException e) {
            assertEquals("Simulated IO Error", e.getMessage());
        }
    }
}
